steps.script:
var ph = PhaseManager.get_current_phase_instance()
var ids = []
for a in ph.get_available_actions():
	if str(a.get("type", "")) == "SELECT_SHOOTER":
		ids.append(str(a.actor_unit_id))
return "%s|%s|%s" % [str("U_BOYZ_F" in ids), str("U_WARBOSS_C" in ids), str("U_WARBOSS_IN_MEGA_ARMOUR_D" in ids)]

var sc = tree.current_scene.get_node("ShootingController")
sc._refresh_unit_list(false)
var l = tree.root.find_child("ShooterUnitList", true, false)
var row = ""
for i in l.get_item_count():
	var uid = str(l.get_item_metadata(i))
	if uid == "U_WARBOSS_C" or uid == "U_WARBOSS_IN_MEGA_ARMOUR_D":
		return "warboss row listed separately"
	if uid == "U_BOYZ_F":
		row = l.get_item_text(i)
return row.contains("+ Warboss") and row.contains("Mega Armour")

var l = tree.root.find_child("ShooterUnitList", true, false)
for i in l.get_item_count():
	if str(l.get_item_metadata(i)) == "U_BOYZ_F":
		l.select(i)
		l.ensure_current_is_visible()
		return l.get_item_text(i).contains("[ACTIVE]")
return false

var sc = tree.current_scene.get_node("ShootingController")
var plan = sc._build_auto_shoot_plan()
var entry = {}
for e in plan:
	if e.unit_id == "U_WARBOSS_C" or e.unit_id == "U_WARBOSS_IN_MEGA_ARMOUR_D":
		return "warboss planned separately"
	if e.unit_id == "U_BOYZ_F":
		entry = e
if entry.is_empty():
	return "no boyz plan"
var char_bearers = 0
for a in entry.assignments:
	for mid in a.model_ids:
		if str(mid).begins_with("U_WARBOSS"):
			char_bearers += 1
sc.emit_signal("shoot_action_requested", {"type": "SHOOT", "actor_unit_id": "U_BOYZ_F", "payload": {"assignments": entry.assignments}})
return char_bearers > 0

var sc = tree.current_scene.get_node("ShootingController")
sc._refresh_unit_list(false)
var l = tree.root.find_child("ShooterUnitList", true, false)
for i in l.get_item_count():
	if str(l.get_item_metadata(i)) == "U_BOYZ_F":
		l.select(i)
		l.ensure_current_is_visible()
		return l.get_item_text(i).ends_with("[SHOT]")
return "missing"
